packagegui.custom_php_validation_command:

// Basic validation: profile must be a known value
$cfg = zapret2_get_config();
$valid_profiles = ['safe', 'default', 'aggressive', 'custom'];
if (!in_array($cfg['profile'] ?? 'default', $valid_profiles, true)) {
    $input_errors[] = 'Invalid Zapret2 profile.';
}
